      publishedOn: "2025-05-05", updatedOn: "2024-10-02",
      heroImage: "https://cdn.prod.website-files.com/6222061ed04f58925e258258/66fc6027710dda0652e10781_series%20b%20hero.webp", thumbnail: "https://cdn.prod.website-files.com/6222061ed04f58925e258258/66fc60be8e28578d31d8ffd4_thumbnail%20post.webp",
      tags: ["Vizit News"],
