      readTime: "4 min",
      description: "Vizit and Salsify have joined forces to elevate ecommerce performance for their shared customers.",
      featured: true, hidden: false, draft: false, archived: false,
      publishedOn: "2025-05-05", updatedOn: "2024-08-28",
      heroImage: "https://cdn.prod.website-files.com/6222061ed04f58925e258258/6601bcc3134c0ba0ae6e3741_blog-hero-image%20(89).png", thumbnail: "https://cdn.prod.website-files.com/6222061ed04f58925e258258/660419d4816f27137d2ae9a7_promotional_post_march_27.webp",
      tags: ["Vizit News"],
